// This file handles all communication with our backend server
import axios from 'axios';

const API = axios.create({
  baseURL: 'http://localhost:5000/api'
});

// Before every request, automatically attach the token if user is logged in
API.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// AUTH
export const registerUser = (data) => API.post('/auth/register', data);
export const loginUser = (data) => API.post('/auth/login', data);

// MEETINGS
export const getMeetings = () => API.get('/meetings');
export const getMeeting = (id) => API.get(`/meetings/${id}`);
export const createMeeting = (data) => API.post('/meetings', data);
export const updateMeeting = (id, data) => API.put(`/meetings/${id}`, data);
export const deleteMeeting = (id) => API.delete(`/meetings/${id}`);
export const respondToMeeting = (id, status) => API.put(`/meetings/${id}/respond`, { status });

// STAFF
export const getStaff = () => API.get('/staff');
export const getMyProfile = () => API.get('/staff/me');
// STAFF MANAGEMENT
export const changeUserRole = (id, role) => API.put(`/staff/${id}/role`, { role });
export const deleteUser = (id) => API.delete(`/staff/${id}`);
